from collections import deque, Counter
def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]; seen=set()
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r in range(h):
      for c in range(w):
        if grid[r][c]==bg and (r,c) not in seen:
          q=deque([(r,c)]); seen.add((r,c)); cells=[]; edge=False
          while q:
            x,y=q.popleft(); cells.append((x,y)); edge |= x==0 or y==0 or x==h-1 or y==w-1
            for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
              if 0<=a<h and 0<=b<w and grid[a][b]==bg and (a,b) not in seen:
                seen.add((a,b)); q.append((a,b))
          if not edge:
            for x,y in cells: out[x][y]=4
    return out
